<?php require 'config.php';
if(isset($_GET['add'])){$id=(int)$_GET['add'];$s=$pdo->prepare("SELECT id FROM products WHERE id=?");$s->execute([$id]);if($s->fetch())$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+1;header('Location: cart.php');exit;}
if(isset($_GET['remove'])){unset($_SESSION['cart'][(int)$_GET['remove']]);header('Location: cart.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){foreach(($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($qty,99);}header('Location: cart.php');exit;}
$cart=$_SESSION['cart']??[];$items=[];$total=0;
if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,pname,price,picture FROM products WHERE id IN ($in)");$s->execute($ids);foreach($s as $r){$r['qty']=$cart[$r['id']];$r['subtotal']=$r['qty']*$r['price'];$total+=$r['subtotal'];$items[]=$r;}}
?><!doctype html><html><head><meta charset="utf-8"><title>Cart</title><link rel="stylesheet" href="assets/style.css"></head><body><main><h1>Shopping Cart</h1><a href="index.php">Continue shopping</a><?php if(!$items):?><p>Your cart is empty.</p><?php else:?><form method="post"><table><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th></th></tr><?php foreach($items as $i):?><tr><td><?=h($i['pname'])?></td><td><?=number_format($i['price'],2)?></td><td><input type="number" min="0" max="99" name="qty[<?=$i['id']?>]" value="<?=$i['qty']?>"></td><td><?=number_format($i['subtotal'],2)?></td><td><a href="cart.php?remove=<?=$i['id']?>">Remove</a></td></tr><?php endforeach;?></table><p><b>Total: <?=number_format($total,2)?></b></p><button>Update cart</button></form><?php endif;?></main></body></html>